(function(){var loadHandler=window['sl_{DB6FE410-0756-4239-AFD9-E5EAE08B52DE}'];loadHandler&&loadHandler(2, '<div id="spr0_3fd3e7"><div id="spr1_3fd3e7" class="kern slide"><img id="img1_3fd3e7" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/></div><div id="spr2_3fd3e7" class="kern slide"><div id="spr3_3fd3e7" aria-label="Изображение выглядит как графическая вставка, мультфильм, Мультфильм  Контент, сгенерированный ИИ, может содержать ошибки." role="group" style="left:33.36px;top:373.534px;"><div id="spr4_3fd3e7"><img id="img0_3fd3e7" src="data:image/png;base64," width="360.75" height="371.25" alt="" style="left:-0.012px;top:-0.122px;"/></div></div><div id="svg0_3fd3e7" style="left:267.686px;top:-109.101px;"><svg width="1118" height="941" viewBox="-6 -121.588 1118 941"><path fill="#ffffff" stroke="#80350e" stroke-width="4" stroke-linecap="butt" stroke-linejoin="miter" stroke-miterlimit="8" d="M168.981,579.928 L2,544.91 L168.981,406.549 V117.588 a115.588,115.588 0 0,1 115.588,-115.588 H872.327 a115.588,115.588 0 0,1 115.588,115.588 V579.925 a115.588,115.588 0 0,1 -115.588,115.588 H284.568 a115.588,115.588 0 0,1 -115.588,-115.588 Z"/></svg></div><div id="spr5_3fd3e7" style="left:273.686px;top:12.487px;"><div style="width:0px;"><span id="txt0_3fd3e7" data-width="693.623657" style="left:232.364px;top:17.245px;">И создал   Бог   зверей   земных  по  роду их,</span></div><div style="width:0px;"><span id="txt1_3fd3e7" data-width="699.942688" style="left:229.198px;top:54.045px;">и  скот  по  роду  его,  и  всех  гадов  земных</span></div><div style="width:0px;"><span id="txt2_3fd3e7" data-width="700.047485" style="left:229.118px;top:90.845px;">по роду их. И  увидел  Бог,  что  это  хорошо.</span></div><div style="width:0px;"><span id="txt3_3fd3e7" data-width="704.644531" style="left:226.698px;top:127.645px;">И  сказал Бог:  сотворим человека по образу</span></div><div style="width:0px;"><span id="txt4_3fd3e7" data-width="688.277954" style="left:235.284px;top:164.445px;">Нашему,    по    подобию     Нашему,    и   да</span></div><div style="width:0px;"><span id="txt5_3fd3e7" data-width="691.961548" style="left:233.198px;top:201.245px;">владычествуют они над рыбами морскими,</span></div><div style="width:0px;"><span id="txt6_3fd3e7" data-width="690.988281" style="left:233.864px;top:238.045px;">и  над  птицами  небесными,  и над скотом,</span></div><div style="width:0px;"><span id="txt7_3fd3e7" data-width="609.065735" style="left:274.864px;top:274.845px;">и   над  всею   землёю,   и    над  всеми</span></div><div style="width:0px;"><span id="txt8_3fd3e7" data-width="604.917969" style="left:276.451px;top:311.645px;">гадами, пресмыкающимися по земле.</span></div><div style="width:0px;"><span id="txt9_3fd3e7" data-width="607.388672" style="left:275.364px;top:348.445px;">И  сотворил   Бог  человека  по  образу</span></div><div style="width:0px;"><span id="txt10_3fd3e7" data-width="662.253235" style="left:247.864px;top:385.245px;"> Своему, по образу  Божию сотворил  его;</span></div><div style="width:0px;"><span id="txt11_3fd3e7" data-width="598.029907" style="left:280.364px;top:422.045px;">мужчину   и   женщину   сотворил   их.</span></div><div style="width:0px;"><span id="txt12_3fd3e7" data-width="596.817017" style="left:280.531px;top:458.845px;">И благословил их Бог, и сказал им Бог:</span></div><div style="width:0px;"><span id="txt13_3fd3e7" data-width="677.361938" style="left:240.451px;top:495.645px;">плодитесь и размножайтесь, и наполняйте</span></div><div style="width:0px;"><span id="txt14_3fd3e7" data-width="673.184204" style="left:242.531px;top:532.445px;">землю, и обладайте ею, и владычествуйте</span></div><div style="width:0px;"><span id="txt15_3fd3e7" data-width="653.822876" style="left:252.531px;top:569.245px;">над  рыбами  морскими,  и  над  птицами</span></div><div style="width:0px;"><span id="txt16_3fd3e7" data-width="625.522095" style="left:266.531px;top:606.045px;">небесными,  и   над  всяким  животным,</span></div><div style="width:0px;"><span id="txt17_3fd3e7" class="relpos" data-width="462.800110" style="left:267.031px;top:642.845px;">пресмыкающимся по земле. </span> <span id="txt18_3fd3e7" class="relpos" data-width="160.572906" style="left:267.024px;top:647.374px;">(Быт.1:25-28)</span></div></div><div id="spr6_3fd3e7" style="left:18.399px;top:28.084px;"><div style="width:0px;"><span id="txt19_3fd3e7" data-width="305.419922" style="left:54.217px;top:16.727px;">Вовчик подошёл к</span></div><div style="width:0px;"><span id="txt20_3fd3e7" data-width="388.232422" style="left:12.637px;top:76.727px;">самому важному дню.</span></div><div style="width:0px;"><span id="txt21_3fd3e7" data-width="390.625000" style="left:11.55px;top:136.727px;">Сегодня разбираемся,</span></div><div style="width:0px;"><span id="txt22_3fd3e7" data-width="323.746735" style="left:44.97px;top:196.727px;">почему    человек -</span></div><div style="width:0px;"><span id="txt23_3fd3e7" data-width="366.406250" style="left:23.637px;top:256.727px;">венец творения и что</span></div><div style="width:0px;"><span id="txt24_3fd3e7" data-width="371.972656" style="left:20.884px;top:316.727px;">значит «образ Божий»</span></div></div></div></div>', '{"s":[]}');})();